const registry = $input.first().json;
if (!registry?.ok || registry.schemaVersion !== 1 || !Array.isArray(registry.targets)) {
  throw new Error('invalid Governor AI source registry');
}
if (registry.targets.length < 1 || registry.targets.length > 200) {
  throw new Error('unexpected AI source target count');
}

return registry.targets.map((target, index) => {
  const url = String(target.url || '');
  if (!url.startsWith('https://')) {
    throw new Error(`target ${index} is not HTTPS`);
  }
  return {
    json: {
      schemaVersion: 1,
      index,
      name: String(target.name || '').slice(0, 200),
      hosts: Array.isArray(target.hosts) ? target.hosts.slice(0, 10) : [],
      checkKind: target.checkKind === 'search' ? 'search' : 'homepage',
      url,
    },
  };
});

const targets = $('Build Bounded Checks').all().map((item) => item.json);
const responses = $input.all().map((item) => item.json);
const state = $getWorkflowStaticData('global');
const monitorSchemaVersion = 3;
const previous = state.monitorSchemaVersion === monitorSchemaVersion && state.baseline && typeof state.baseline === 'object' ? state.baseline : {};
const now = new Date().toISOString();

function hashText(value) {
  let hash = 2166136261;
  for (let i = 0; i < value.length; i += 1) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

function structureOf(body) {
  const text = String(body || '').slice(0, 20000).replace(/\s+/g, ' ');
  const title = (text.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1] || '')
    .replace(/<[^>]+>/g, '').trim().slice(0, 300);
  const forms = [...text.matchAll(/<form\b[^>]*>/gi)].slice(0, 20).map((match) => {
    const tag = match[0];
    const method = (tag.match(/\bmethod=(["'])([^"']+)\1/i)?.[2] || 'get').toLowerCase();
    const actionValue = tag.match(/\baction=(["'])([^"']*)\1/i)?.[2] || '';
    const action = actionValue.split(/[?#]/, 1)[0].toLowerCase();
    return { method, action };
  });
  const fields = [...text.matchAll(/<(input|select|textarea)\b[^>]*\bname=(["'])([^"']+)\2[^>]*>/gi)]
    .slice(0, 80).map((match) => ({ tag: match[1].toLowerCase(), name: match[3].toLowerCase() }))
    .sort((left, right) => `${left.tag}:${left.name}`.localeCompare(`${right.tag}:${right.name}`));
  return { title, formCount: forms.length, fieldCount: fields.length, fingerprint: hashText(JSON.stringify({ forms, fields })) };
}

const current = {};
const checks = [];
const changes = [];
for (let index = 0; index < targets.length; index += 1) {
  const target = targets[index];
  const response = responses[index] || {};
  const statusCode = Number(response.statusCode || 0);
  const error = String(response.error?.message || response.error || '').slice(0, 500);
  const available = !error && statusCode >= 200 && statusCode < 400;
  const headers = response.headers && typeof response.headers === 'object' ? response.headers : {};
  const structure = structureOf(response.data ?? response.body);
  const snapshot = {
    name: target.name,
    url: target.url,
    checkKind: target.checkKind,
    available,
    statusCode,
    contentType: String(headers['content-type'] || headers['Content-Type'] || '').slice(0, 200),
    etag: String(headers.etag || headers.ETag || '').slice(0, 300),
    lastModified: String(headers['last-modified'] || headers['Last-Modified'] || '').slice(0, 200),
    title: structure.title,
    formCount: structure.formCount,
    fieldCount: structure.fieldCount,
    structureFingerprint: structure.fingerprint,
    error,
    checkedAt: now,
  };
  current[target.name] = snapshot;
  checks.push(snapshot);
  const before = previous[target.name];
  if (!before) continue;
  if (before.available !== snapshot.available) {
    changes.push({ name: target.name, type: snapshot.available ? 'recovered' : 'unavailable', before: before.statusCode, after: snapshot.statusCode, error });
  } else if (before.statusCode !== snapshot.statusCode) {
    changes.push({ name: target.name, type: 'status_changed', before: before.statusCode, after: snapshot.statusCode });
  } else if (before.url !== snapshot.url) {
    changes.push({ name: target.name, type: 'monitor_url_changed', before: before.url, after: snapshot.url });
  } else if (target.checkKind === 'search' && before.structureFingerprint !== snapshot.structureFingerprint) {
    changes.push({ name: target.name, type: 'search_structure_changed', before: before.structureFingerprint, after: snapshot.structureFingerprint });
  }
}

const removed = Object.keys(previous).filter((name) => !current[name]);
for (const name of removed) changes.push({ name, type: 'removed_from_allowlist' });
const baselineCreated = Object.keys(previous).length === 0;
state.monitorSchemaVersion = monitorSchemaVersion;
state.baseline = current;
state.lastRun = now;
state.lastChanges = changes.slice(0, 200);

return [{ json: {
  ok: true,
  schemaVersion: monitorSchemaVersion,
  checkedAt: now,
  baselineCreated,
  checkedCount: checks.length,
  availableCount: checks.filter((item) => item.available).length,
  unavailableCount: checks.filter((item) => !item.available).length,
  changedCount: changes.length,
  changes: changes.slice(0, 200),
  checks,
} }];
